import * as Cesium from 'cesium';
import { normalizeFeature } from '../core/schema.js';
import { colorFor } from '../core/colors.js';
import { svgDot } from '../core/icons.js';

// --- CRS + props helpers ---
const __wmProj = new Cesium.WebMercatorProjection();

function ring3857ToDegrees(ring) {
    // ring is [[x,y], [x,y], ...] in EPSG:3857
    const out = [];
    for (const [x, y] of ring) {
        const carto = __wmProj.unproject(new Cesium.Cartesian3(x, y, 0));
        out.push(Cesium.Math.toDegrees(carto.longitude), Cesium.Math.toDegrees(carto.latitude));
    }
    return out;
}

function normalizeProps(raw = {}) {
    const p = raw || {};
    const hazardType = (p.hazardType ?? p.hazard_type ?? p.Name ?? 'unknown')
        .toString()
        .toLowerCase();
    const medium = (p.environmentalMedium ?? p.environmental_medium ?? 'unknown')
        .toString()
        .toLowerCase();
    const severity = Number.parseInt(p.severity ?? p.severity_level ?? p.Code ?? 1, 10) || 1;
    const location = (p.locationDescription ?? p.location_description ?? p.Name ?? 'Unknown location');
    return { hazardType, medium, severity, location };
}

function _centroidFromDegreesArray(degs) {
    // degs: [lon,lat, lon,lat, ...]
    let sx = 0, sy = 0, n = 0;
    for (let i = 0; i < degs.length; i += 2) {
        sx += degs[i];
        sy += degs[i+1];
        n++;
    }
    if (!n) return { lon: 0, lat: 0 };
    return { lon: sx / n, lat: sy / n };
}

export class HazardManager {
    constructor(viewer) {
        this.viewer = viewer;
        this.hazardData = [];
        this.hazardEntities = [];
        this.selectedHazard = null;
        this.isWebMercator = false;
        this._adaptiveOn = false;
        this._lastAdaptiveState = null;

        // Debug: force-show all polygons on demand
        window.__showAllPolys = () => {
            (this.hazardEntities || []).forEach(e => {
                if (e && e.entity) {
                    e.entity.show = true;
                    if (e.pinEntity) e.pinEntity.show = true;
                } else if (e) {
                    e.show = true;
                }
            });
            console.log(`Forced show on ${(this.hazardEntities || []).length} entities.`);
        };
    }

    enableAdaptiveVisibility() {
        if (this._adaptiveOn) return;
        this._adaptiveOn = true;
        const scene = this.viewer.scene;
        const handler = () => this._updateAdaptivePolygons();
        this._postRenderCb = handler;
        scene.postRender.addEventListener(handler);
    }

    disableAdaptiveVisibility() {
        if (!this._adaptiveOn) return;
        this._adaptiveOn = false;
        if (this._postRenderCb) {
            this.viewer.scene.postRender.removeEventListener(this._postRenderCb);
            this._postRenderCb = null;
        }
    }

    _updateAdaptivePolygons() {
        const hasGoogleTiles = this.viewer?.scene?.primitives?._primitives?.some(p =>
            typeof p._resource?.url === 'string' && p._resource.url.includes('tile.googleapis.com/v1/3dtiles')
        );
        if (!hasGoogleTiles) return; // only adapt when classifying over Google tiles

        const h = this.viewer.camera.positionCartographic.height || 0;
        const makeLifted = h < 900; // lift when very close
        if (makeLifted === this._lastAdaptiveState) return;
        this._lastAdaptiveState = makeLifted;

        const list = this.hazardEntities || [];
        for (const item of list) {
            const ent = item?.entity ?? item;
            if (!ent || !ent.polygon) continue;
            if (makeLifted) {
                ent.polygon.classificationType = undefined;
                ent.polygon.height = 5;
                ent.polygon.perPositionHeight = false;
                ent.polygon.disableDepthTestDistance = Number.POSITIVE_INFINITY;
            } else {
                ent.polygon.disableDepthTestDistance = undefined;
                ent.polygon.height = undefined;
                ent.polygon.perPositionHeight = false;
                ent.polygon.classificationType = Cesium.ClassificationType.CESIUM_3D_TILE;
            }
        }
    }

    // Load hazard data from GeoJSON file
    async loadHazardData(dataFile) {
        try {
            const response = await fetch(dataFile);
            if (!response.ok) {
                throw new Error(`Failed to load data: ${response.statusText}`);
            }
            
            const geojson = await response.json();
            this.isWebMercator = this.detectWebMercatorCRS(geojson);
            this.processHazardData(geojson);
            console.log(`Loaded ${this.hazardData.length} hazard features`);
        } catch (error) {
            console.error('Error loading hazard data:', error);
            throw error;
        }
    }

    // Process GeoJSON data and create hazard entities
    processHazardData(geojson) {
        this.hazardData = geojson.features || [];

        let entityIndex = 0;
        this.hazardData.forEach((feature) => {
            const geometry = feature.geometry;
            if (!geometry) return;

            if (geometry.type === 'Polygon') {
                this.createHazardEntity(feature, entityIndex++);
            } else if (geometry.type === 'MultiPolygon') {
                // Create an entity for each polygon in the multipolygon
                const polygons = geometry.coordinates || [];
                polygons.forEach((polygonCoords) => {
                    const single = { ...feature, geometry: { type: 'Polygon', coordinates: polygonCoords } };
                    this.createHazardEntity(single, entityIndex++);
                });
            }
        });
    }

    // Create polygon entities for Polygon and MultiPolygon using addPolygonEntity helper
    createHazardEntity(feature, idx) {
        const geom = feature?.geometry;
        if (!geom || !geom.type || !geom.coordinates) return;

        if (geom.type === 'Polygon') {
            // geom.coordinates = [ outerRing, hole1?, hole2? ... ]
            this.addPolygonEntity(geom.coordinates[0], feature.properties, idx);
        } else if (geom.type === 'MultiPolygon') {
            // geom.coordinates = [ [ polygonA_rings ], [ polygonB_rings ], ... ]
            geom.coordinates.forEach((polyRings, i) => {
                this.addPolygonEntity(polyRings[0], feature.properties, `${idx}-${i}`);
            });
        } else {
            // Other geometry types not handled here
        }
    }

    // Convert a ring [[x,y],...] to flat degrees array [lon,lat,...]
    ringToDegreesArray(ring, isWebMercator) {
        const result = [];
        for (let i = 0; i < ring.length; i++) {
            const pt = ring[i];
            if (!pt || pt.length < 2) continue;
            const lonlat = isWebMercator ? this.webMercatorToLonLat(pt[0], pt[1]) : { lon: pt[0], lat: pt[1] };
            result.push(lonlat.lon, lonlat.lat);
        }
        return result;
    }

    // Calculate centroid from a ring in either 3857 or 4326
    calculateCentroidFromRing(ring, isWebMercator) {
        let sx = 0;
        let sy = 0;
        let n = 0;
        for (let i = 0; i < ring.length; i++) {
            const pt = ring[i];
            if (!pt || pt.length < 2) continue;
            const lonlat = isWebMercator ? this.webMercatorToLonLat(pt[0], pt[1]) : { lon: pt[0], lat: pt[1] };
            sx += lonlat.lon;
            sy += lonlat.lat;
            n++;
        }
        if (n === 0) return { longitude: 0, latitude: 0 };
        return { longitude: sx / n, latitude: sy / n };
    }

    // Detect if FeatureCollection uses EPSG:3857
    detectWebMercatorCRS(geojson) {
        const name = geojson?.crs?.properties?.name || geojson?.crs?.properties?.code || '';
        return /3857|102100|web\s*mercator/i.test(String(name));
    }

    // Convert Web Mercator meters (EPSG:3857) to lon/lat degrees (EPSG:4326)
    webMercatorToLonLat(x, y) {
        const R = 6378137.0;
        const lon = (x / R) * 180 / Math.PI;
        const lat = (2 * Math.atan(Math.exp(y / R)) - (Math.PI / 2)) * 180 / Math.PI;
        return { lon, lat };
    }

    // Focused helper to add one polygon entity given a 3857 ring and raw properties
    addPolygonEntity(ring3857, rawProps, keySuffix = '') {
        let degs = ring3857ToDegrees(ring3857);
        // Ensure ring closed to avoid rendering artifacts
        if (degs.length >= 4) {
            const fx = degs[0], fy = degs[1];
            const lx = degs[degs.length - 2], ly = degs[degs.length - 1];
            if (fx !== lx || fy !== ly) {
                degs = degs.concat([fx, fy]);
            }
        }
        const props = normalizeProps(rawProps);

        const hasGoogleTiles = this.viewer?.scene?.primitives?._primitives?.some(p =>
            typeof p._resource?.url === 'string' && p._resource.url.includes('tile.googleapis.com/v1/3dtiles')
        );

        const polygonOpts = {
            hierarchy: Cesium.Cartesian3.fromDegreesArray(degs),
            material: Cesium.Color.fromCssColorString('#ffcc00').withAlpha(0.85),
            outline: true,
            outlineColor: Cesium.Color.BLACK,
            classificationType: hasGoogleTiles
                ? Cesium.ClassificationType.CESIUM_3D_TILE
                : Cesium.ClassificationType.TERRAIN
        };

        const entity = this.viewer.entities.add({
            id: `haz-${props.hazardType}-${keySuffix}-${Math.random().toString(36).slice(2,7)}`,
            polygon: polygonOpts,
            properties: {
                hazardType: props.hazardType,
                medium: props.medium,
                severity: props.severity,
                location: props.location,
                raw: rawProps,
            },
        });

        // Beacon: always-visible point and a subtle pulsating ring for Gym Sauna
        if (props.hazardType === 'gym sauna') {
            const c = _centroidFromDegreesArray(degs);

            // Always-visible point (sits ~30m above ground; ignores depth)
            const beaconPoint = this.viewer.entities.add({
                position: Cesium.Cartesian3.fromDegrees(c.lon, c.lat, 30),
                point: {
                    pixelSize: 16,
                    color: Cesium.Color.CHARTREUSE.withAlpha(0.95),
                    outlineColor: Cesium.Color.BLACK,
                    outlineWidth: 2,
                    // show even if behind meshes
                    disableDepthTestDistance: Number.POSITIVE_INFINITY
                },
                properties: { parentHazard: entity.id }
            });

            // Optional pulsating ground ring (helps draw attention)
            const pulse = new Cesium.CallbackProperty(
                () => 12 + 8 * Math.abs(Math.sin(Date.now() / 600)),
                false
            );

            const ring = this.viewer.entities.add({
                position: Cesium.Cartesian3.fromDegrees(c.lon, c.lat, 5),
                ellipse: {
                    semiMajorAxis: pulse,
                    semiMinorAxis: pulse,
                    // Drape onto tiles if present; otherwise over terrain
                    classificationType: Cesium.ClassificationType.CESIUM_3D_TILE,
                    material: Cesium.Color.CHARTREUSE.withAlpha(0.25),
                    outline: true,
                    outlineColor: Cesium.Color.CHARTREUSE
                },
                properties: { parentHazard: entity.id }
            });
        }

        this.hazardEntities ??= [];
        this.hazardEntities.push(entity);
        return entity;
    }

    // Get material color based on hazard type and severity using centralized colors
    getHazardMaterial(hazardType, severity) {
        const alpha = 0.3 + (severity * 0.1); // 0.4 to 0.8 based on severity
        return colorFor(hazardType, alpha);
    }

    // Get severity color for outlines
    getSeverityColor(severity) {
        const colors = [
            Cesium.Color.LIGHTGREEN,  // 1
            Cesium.Color.YELLOW,      // 2
            Cesium.Color.ORANGE,      // 3
            Cesium.Color.RED,         // 4
            Cesium.Color.DARKRED      // 5
        ];
        return colors[Math.min(severity - 1, 4)] || Cesium.Color.GRAY;
    }

    // Get outline width based on severity
    getSeverityOutlineWidth(severity) {
        return Math.min(2 + severity, 6);
    }

    // Get hazard icon using centralized icon generation
    getHazardIcon(hazardType) {
        const color = this.getHazardTypeColor(hazardType);
        return svgDot(color);
    }

    // Get hazard type color using centralized colors
    getHazardTypeColor(hazardType) {
        const colors = {
            chemical: '#FFD700',
            biological: '#32CD32',
            radiological: '#FF8C00',
            nuclear: '#FF0000',
            environmental: '#4169E1',
            physical: '#8A2BE2'
        };
        return colors[hazardType.toLowerCase()] || '#808080';
    }

    // Get all hazard entities (normalize to { entity, pinEntity } for downstream consumers)
    getHazardEntities() {
        const list = this.hazardEntities || [];
        // If items are raw entities, wrap them
        if (list.length > 0 && !('entity' in list[0])) {
            return list.map((e) => ({ entity: e, pinEntity: undefined }));
        }
        return list;
    }

    // Get hazard data
    getHazardData() {
        return this.hazardData;
    }

    // Set selected hazard
    setSelectedHazard(hazard) {
        this.selectedHazard = hazard;
    }

    // Get selected hazard
    getSelectedHazard() {
        return this.selectedHazard;
    }
}